    access_requests = payload.get("access_requests", {})
    result = {}
    for rid, req in access_requests.items():
        roles = sorted(req.get("roles") or [])
        resources = sorted(req.get("resources") or [])
        result[rid] = {
            "approved": req.get("approved", False),
            "expiry": req.get("expiry"),
            "roles": roles,
            "resources": resources,
        }
    return result

