def compute(payload):
    """记录各续期事件发生时的用户快照，重放 update_user 的 roles、traits；以原位置字符串为键。"""
    user = payload.get("user", {})
    events = payload.get("events", [])

    current = {
        "name": user.get("name"),
        "roles": list(user.get("roles", [])),
        "traits": copy.deepcopy(user.get("traits", {})),
    }

    result = {}
    for index, event in enumerate(events):
        op = event.get("op")
        if op == "update_user":
            if "roles" in event:
                current["roles"] = list(event["roles"])
            if "traits" in event:
                current["traits"] = copy.deepcopy(event["traits"])
        elif op == "renew":
            result[str(index)] = copy.deepcopy(current)

    return result

import json
import sys
import unittest
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[3]))
from components.user_history.work import compute


class TestUserHistory(unittest.TestCase):
    def test_snapshot_at_renew(self):
        payload = {
            "user": {
                "name": "alice",
                "roles": ["base"],
                "traits": {"logins": ["alice"], "db_users": ["db1"]},
            },
            "events": [
                {"op": "renew", "id": "s1", "time": 10, "prev": "s0"},
            ],
        }
        result = compute(payload)
        self.assertEqual(
            result,
            {
                "0": {
                    "name": "alice",
                    "roles": ["base"],
                    "traits": {"logins": ["alice"], "db_users": ["db1"]},
                }
            },
        )

    def test_update_user_replays_roles_and_traits(self):
        payload = {
            "user": {
                "name": "bob",
                "roles": ["base"],
                "traits": {"logins": ["bob"], "db_users": ["db1"]},
            },
            "events": [
                {"op": "update_user", "roles": ["admin"], "traits": {"logins": ["bob2"], "db_users": ["db2"]}},
                {"op": "renew", "id": "s1", "time": 5, "prev": "s0"},
                {"op": "update_user", "roles": ["reader"]},
                {"op": "renew", "id": "s2", "time": 9, "prev": "s1"},
            ],
        }
        result = compute(payload)
        self.assertEqual(result["1"]["roles"], ["admin"])
        self.assertEqual(result["1"]["traits"], {"logins": ["bob2"], "db_users": ["db2"]})
        # second update only replaces roles, traits preserved
        self.assertEqual(result["3"]["roles"], ["reader"])
        self.assertEqual(result["3"]["traits"], {"logins": ["bob2"], "db_users": ["db2"]})

    def test_does_not_mutate_input(self):
        payload = {
            "user": {
                "name": "carol",
                "roles": ["base"],
                "traits": {"logins": ["carol"], "db_users": ["db1"]},
            },
            "events": [
                {"op": "update_user", "roles": ["x"]},
                {"op": "renew", "id": "s1", "time": 1, "prev": "s0"},
            ],
        }
        before = json.dumps(payload, sort_keys=True)
        compute(payload)
        self.assertEqual(json.dumps(payload, sort_keys=True), before)


if __name__ == "__main__":
    unittest.main()

